import { readDisplaySnapshot, writeDisplaySnapshot } from '../app/local-display-cache.js';
import { readClaimableEth } from '../app/claims.js';
import { TX_CONFIRMED_EVENT } from '../app/contracts.js';
import { registerComponentPoll } from '../app/component-poll.js';
import { get, getActingAddress, getViewedAddress, subscribe } from '../app/store.js';
import { displayEthCompact, displayToken } from '../app/scaling.js';
import { openPlayerFundsDialog } from '../app/player-funds.js';
import { setActionFeedback } from '../two-widget-hub/action-feedback.js';

const address = value => String(value || '').toLowerCase() || null;

function scopedDisclosure(key, owner) {
  const snapshot = get(key);
  if (!owner) return null;
  const cacheKey = `token-disclosure:${owner}:${key}`;
  // Persist only the value already disclosed by the owning widget. Never
  // publish a stored number into live balances or transaction calculations.
  if (address(snapshot?.address) === owner
    && (snapshot.valueWei != null || snapshot.known === true)) {
    writeDisplaySnapshot(cacheKey, snapshot);
    return snapshot;
  }
  return readDisplaySnapshot(cacheKey)?.value ?? null;
}

function formatFlip(value) {
  const whole = BigInt(displayToken(value, 0));
  return new Intl.NumberFormat('en-US', {
    notation: whole >= 10_000n ? 'compact' : 'standard',
    maximumFractionDigits: 1,
  }).format(whole);
}

export class AppTokenFunds extends HTMLElement {
  #unsubs = [];
  #openingAfking = false;
  #ethRequest = 0;
  #refreshEth = async () => {
    const owner = this.#owner();
    const request = ++this.#ethRequest;
    this.#render();
    if (!owner) return;
    const raw = await readClaimableEth({ player: owner });
    if (!this.isConnected || request !== this.#ethRequest || owner !== this.#owner()) return;
    if (raw != null) {
      // The contract's raw view includes its non-withdrawable one-wei sentinel.
      writeDisplaySnapshot(`token-claimable-eth:${owner}`, raw > 1n ? raw - 1n : 0n);
    }
    this.#render();
  };

  #owner() {
    return get('ui.mode') === 'combined' ? null : address(getViewedAddress());
  }

  connectedCallback() {
    if (this.#unsubs.length) return;
    this.innerHTML = `
      <section class="token-fund token-fund--flip" aria-label="Available FLIP">
        <img class="token-fund__badge" src="/shared/flip-chips/face.svg" alt="" aria-hidden="true">
        <strong class="token-fund__amount"><b data-bind="token-flip">—</b><em>FLIP</em></strong>
        <button type="button" data-funds="flip" aria-haspopup="dialog" disabled>CASH OUT</button>
      </section>
      <section class="token-fund token-fund--eth" aria-label="Claimable ETH">
        <img class="token-fund__badge" src="/shared/coinflip-face-eth.svg" alt="" aria-hidden="true">
        <strong class="token-fund__amount"><b data-bind="token-eth">—</b><em>ETH</em></strong>
        <button type="button" data-funds="eth" aria-haspopup="dialog" disabled>CLAIM ETH</button>
      </section>
      <section class="token-fund token-fund--afking" aria-label="AFKing funding" hidden>
        <img class="token-fund__badge" src="/app/assets/afking-subscription-teal-ember.svg" alt="" aria-hidden="true">
        <strong class="token-fund__amount"><b data-bind="token-afking">—</b><em>ETH</em></strong>
        <button type="button" data-manage-afking data-bind="token-afking-note" aria-haspopup="dialog" aria-label="Manage AFKing funding" title="Edit AFKing funding">— DAYS FUNDED</button>
        <span data-bind="token-afking-error" role="alert" hidden></span>
      </section>`;
    for (const button of this.querySelectorAll('[data-funds]')) {
      button.addEventListener('click', () => {
        if (!button.disabled) openPlayerFundsDialog(button.dataset.funds);
      });
    }
    const manage = this.querySelector('[data-manage-afking]');
    manage.addEventListener('click', async () => {
      if (manage.disabled || this.#openingAfking) return;
      const owner = getActingAddress();
      this.#openingAfking = true;
      manage.disabled = true;
      manage.setAttribute('aria-busy', 'true');
      const feedback = this.querySelector('[data-bind="token-afking-error"]');
      setActionFeedback(feedback, '');
      try {
        await import('./app-pass-section.js');
        if (!this.isConnected || getActingAddress() !== owner) return;
        const panel = document.querySelector('app-pass-section');
        if (!await panel?.openAfkingEditor(manage)) {
          setActionFeedback(feedback, 'AFKing funding is still loading. Try again.');
        }
      } catch (_error) {
        setActionFeedback(feedback, 'Could not open AFKing funding. Try again.');
      } finally {
        this.#openingAfking = false;
        manage.removeAttribute('aria-busy');
        this.#render();
      }
    });
    for (const key of ['connected.address', 'viewing.address', 'ui.mode']) {
      this.#unsubs.push(subscribe(key, this.#refreshEth));
    }
    for (const key of ['ui.protocolCoinsFlipDisclosure', 'app.afkingSubscription']) {
      this.#unsubs.push(subscribe(key, () => this.#render()));
    }
    this.#unsubs.push(registerComponentPoll(this.#refreshEth, 30_000, { owner: this }));
    document.addEventListener(TX_CONFIRMED_EVENT, this.#refreshEth);
    this.#unsubs.push(() => document.removeEventListener(TX_CONFIRMED_EVENT, this.#refreshEth));
    void this.#refreshEth();
  }

  disconnectedCallback() {
    ++this.#ethRequest;
    for (const unsubscribe of this.#unsubs.splice(0)) unsubscribe();
  }

  #render() {
    const owner = this.#owner();
    const canAct = Boolean(owner && address(getActingAddress()) === owner);
    for (const [asset, key] of [['flip', 'ui.protocolCoinsFlipDisclosure'], ['eth', 'ui.claimableEthDisclosure']]) {
      // ETH is a live account balance, independent of the hidden Buy In panel's
      // animation/reveal state. Keep the last successful read through RPC failures.
      const snapshot = asset === 'eth'
        ? { valueWei: owner ? readDisplaySnapshot(`token-claimable-eth:${owner}`)?.value : null }
        : scopedDisclosure(key, owner);
      const value = this.querySelector(`[data-bind="token-${asset}"]`);
      let raw = null;
      try { if (snapshot?.valueWei != null) raw = BigInt(snapshot.valueWei); } catch (_) { /* unknown */ }
      value.textContent = raw == null ? '—' : asset === 'flip' ? formatFlip(raw) : displayEthCompact(raw, 2);
      value.style.setProperty('--token-amount-chars', String(value.textContent.length));
      value.title = raw == null ? '' : asset === 'flip'
        ? `${displayToken(raw, 0)} FLIP available` : `${displayEthCompact(raw)} ETH claimable`;
      this.querySelector(`[data-funds="${asset}"]`).disabled = !canAct;
    }
    const subscription = scopedDisclosure('app.afkingSubscription', owner);
    const afking = this.querySelector('.token-fund--afking');
    afking.hidden = subscription?.active !== true;
    const days = subscription?.known === true ? subscription.fundedDays : null;
    const funding = subscription?.known === true ? subscription.fundingWei : null;
    const fundingAmount = this.querySelector('[data-bind="token-afking"]');
    fundingAmount.textContent = funding == null ? '—' : displayEthCompact(BigInt(funding), 2);
    fundingAmount.style.setProperty('--token-amount-chars', String(fundingAmount.textContent.length));
    const manage = this.querySelector('[data-manage-afking]');
    manage.textContent = days == null ? '— DAYS FUNDED'
      : `${days} ${String(days) === '1' ? 'DAY' : 'DAYS'} FUNDED`;
    manage.setAttribute('aria-label', `Manage AFKing funding: ${manage.textContent.toLowerCase()}`);
    afking.classList.toggle('is-low', days != null && BigInt(days) < 7n);
    afking.querySelector('button').disabled = !canAct || this.#openingAfking;
  }
}

if (!customElements.get('app-token-funds')) customElements.define('app-token-funds', AppTokenFunds);
